#### Task:
- Assign the subdomains to bounded contexts. 
- Name the subdomain the bounded context might be derived from, it might also be multiple.
- Identify cases, where an object does not have a unified meaning across all bounded contexts and suggest a name change.
- Return the bounded contexts in json format. Here is an example for structuring the data:
```json
{
  "bounded contexts": {
    "...": {
      "derived from": "...",
      "objects": [
        "...",
        "..."
      ],
      "name changes": []
    },
    "...": {
      "derived from": "...",
      "objects": [
        "...",
        "...",
        "..."
      ],
      "name changes": [
        "... -> ..."
      ]
    }
  }
}
```

Here are the bounded contexts: 
```json
{
  "bounded contexts": {
    "Supervision": {
      "derived from": "Supervision Subdomain",
      "objects": [
        "Collection Manager",
        "Route Schedule"
      ],
      "name changes": []
    },
    "Maintenance": {
      "derived from": "Maintenance Subdomain",
      "objects": [
        "Maintenance Supervisor",
        "Preventive Maintenance",
        "Asset Vehicle",
        "Maintenance Records"
      ],
      "name changes": [
        "Waste Truck -> Asset Vehicle"
      ]
    },
    "Recycling": {
      "derived from": "Recycling Subdomain",
      "objects": [
        "Recycling Coordinator",
        "Sorting Facility",
        "Contamination Issue",
        "Material Transfer",
        "Partner Recycling Plant"
      ],
      "name changes": []
    },
    "Client Request": {
      "derived from": "Client Request Subdomain",
      "objects": [
        "Client",
        "Pickup Request",
        "Requested Location"
      ],
      "name changes": [
        "Pickup Location -> Requested Location"
      ]
    },
    "Route Planning": {
      "derived from": "Route Planning Subdomain",
      "objects": [
        "Route Planner",
        "Traffic Data",
        "Route Plan",
        "Location Assignment",
        "Truck Assignment",
        "Collection Zone",
        "Vehicle Capacity"
      ],
      "name changes": [
        "Collection Route -> Route Plan",
        "Pickup Location -> Location Assignment",
        "Waste Truck -> Truck Assignment"
      ]
    },
    "Waste Collection": {
      "derived from": "Waste Collection Subdomain",
      "objects": [
        "Driver",
        "Collection Route",
        "Waste Truck",
        "Pickup Location",
        "Route Log",
        "Issue Report"
      ],
      "name changes": []
    }
  }
}
```
